 1→import { inject, Injectable, signal } from '@angular/core';
 2→import { FretNote } from './note-data';
 3→import { ProgressionService } from './progression.service';
 4→
 5→export enum GameState {
 6→  IDLE = 'IDLE',
 7→  SHOW_NOTE = 'SHOW_NOTE',
 8→  SHOW_ANSWER = 'SHOW_ANSWER',
 9→}
10→
11→@Injectable()
12→export class GameStateService {
13→  private readonly progression = inject(ProgressionService);
14→
15→  private readonly _state = signal<GameState>(GameState.IDLE);
16→  private readonly _currentNote = signal<FretNote | null>(null);
17→
18→  readonly state = this._state.asReadonly();
19→  readonly currentNote = this._currentNote.asReadonly();
20→
21→  start(): void {
22→    if (this._state() !== GameState.IDLE) {
23→      return;
24→    }
25→    this._currentNote.set(this.progression.drawNote());
26→    this._state.set(GameState.SHOW_NOTE);
27→  }
28→
29→  showAnswer(): void {
30→    if (this._state() !== GameState.SHOW_NOTE) {
31→      return;
32→    }
33→    this._state.set(GameState.SHOW_ANSWER);
34→  }
35→
36→  nextNote(): void {
37→    if (this._state() !== GameState.SHOW_ANSWER) {
38→      return;
39→    }
40→    this._currentNote.set(this.progression.drawNote());
41→    this._state.set(GameState.SHOW_NOTE);
42→  }
43→
44→  stop(): void {
45→    this._currentNote.set(null);
46→    this._state.set(GameState.IDLE);
47→    this.progression.reset();
48→  }
49→}
