158→  describe('full cycle', () => {
159→    it('should complete a full game cycle: IDLE -> SHOW_NOTE -> SHOW_ANSWER -> SHOW_NOTE (next)', () => {
160→      const progression = TestBed.inject(ProgressionService);
161→      vi.spyOn(progression, 'drawNote');
162→
163→      expect(service.state()).toBe(GameState.IDLE);
164→
165→      service.start();
