167→      const firstNote = service.currentNote();
168→      expect(firstNote).not.toBeNull();
169→      expect(progression.drawNote).toHaveBeenCalledTimes(1);
170→
171→      service.showAnswer();
172→      expect(service.state()).toBe(GameState.SHOW_ANSWER);
173→      expect(service.currentNote()).toBe(firstNote);
174→
175→      service.nextNote();
176→      expect(service.state()).toBe(GameState.SHOW_NOTE);
177→      expect(service.currentNote()).not.toBeNull();
178→      expect(progression.drawNote).toHaveBeenCalledTimes(2);
179→    });
180→
181→    it('should be able to run multiple cycles', () => {
182→      service.start();
183→
184→      for (let i = 0; i < 5; i++) {
185→        expect(service.state()).toBe(GameState.SHOW_NOTE);
186→        expect(service.currentNote()).not.toBeNull();
187→
188→        service.showAnswer();
189→        expect(service.state()).toBe(GameState.SHOW_ANSWER);
190→
191→        service.nextNote();
192→      }
193→
194→      expect(service.state()).toBe(GameState.SHOW_NOTE);
195→    });
196→  });
197→});
