 1→export type NaturalNote = 'C' | 'D' | 'E' | 'F' | 'G' | 'A' | 'B';
 2→
 3→export interface FretNote {
 4→  string: number;      // 1-6 (1 = high E, 6 = low E)
 5→  fret: number;        // 0-15 (0 = open)
 6→  note: NaturalNote;   // natural note name
 7→  x: number;           // x position on fretboard image (%)
 8→  y: number;           // y position on fretboard image (%)
 9→}
10→
11→/**
12→ * Chromatic scale used to derive natural notes per string.
13→ * Standard guitar tuning: E-A-D-G-B-E (string 6 to 1).
14→ */
15→const CHROMATIC_SCALE = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'] as const;
16→
17→const NATURAL_NOTES: ReadonlySet<string> = new Set<NaturalNote>(['C', 'D', 'E', 'F', 'G', 'A', 'B']);
18→
19→/** Open string notes in standard tuning, indexed by string number (1-6). */
20→const OPEN_STRING_NOTES: Record<number, NaturalNote> = {
21→  1: 'E', // high E
22→  2: 'B',
23→  3: 'G',
24→  4: 'D',
25→  5: 'A',
26→  6: 'E', // low E
27→};
28→
29→/**
30→ * Y-position (%) for each string on the fretboard image.
31→ * String 6 (low E) is at the bottom, string 1 (high E) at the top.
32→ */
33→const STRING_Y_POSITIONS: Record<number, number> = {
34→  1: 8,
35→  2: 25,
36→  3: 42,
37→  4: 58,
38→  5: 75,
39→  6: 92,
40→};
41→
42→/**
43→ * X-position (%) for each fret on the fretboard image.
44→ * Fret 0 (open/nut) is on the far left, fret 15 on the far right.
45→ * Positions approximate the midpoint of each fret space.
46→ */
47→function fretXPosition(fret: number): number {
48→  if (fret === 0) {
49→    return 1.5;
50→  }
51→  // Frets 1-15 distributed across roughly 6% to 97% of the image width
52→  // Real fretboard spacing decreases toward higher frets, but we use
53→  // approximate linear spacing since these will be fine-tuned later.
54→  return 3 + (fret / 15) * 94;
55→}
56→
57→function generateFretNotes(): FretNote[] {
58→  const notes: FretNote[] = [];
59→
60→  for (let guitarString = 1; guitarString <= 6; guitarString++) {
61→    const openNote = OPEN_STRING_NOTES[guitarString];
62→    const startIndex = CHROMATIC_SCALE.indexOf(openNote as typeof CHROMATIC_SCALE[number]);
63→
64→    for (let fret = 0; fret <= 15; fret++) {
65→      const noteIndex = (startIndex + fret) % 12;
66→      const noteName = CHROMATIC_SCALE[noteIndex];
67→
68→      if (NATURAL_NOTES.has(noteName)) {
69→        notes.push({
70→          string: guitarString,
71→          fret,
72→          note: noteName as NaturalNote,
73→          x: fretXPosition(fret),
74→          y: STRING_Y_POSITIONS[guitarString],
75→        });
76→      }
77→    }
78→  }
79→
80→  return notes;
81→}
82→
83→/** All natural notes (C, D, E, F, G, A, B) on frets 0-15, all 6 strings in standard tuning. */
84→export const FRET_NOTES: readonly FretNote[] = generateFretNotes();
