 1→import { inject, Injectable, OnDestroy, signal } from '@angular/core';
 2→import { FretNote } from './note-data';
 3→import { ProgressionService } from './progression.service';
 4→
 5→export enum GameState {
 6→  IDLE = 'IDLE',
 7→  SHOW_NOTE = 'SHOW_NOTE',
 8→  SHOW_ANSWER = 'SHOW_ANSWER',
 9→}
10→
11→export const SHOW_NOTE_DURATION_MS = 5000;
12→export const SHOW_ANSWER_DURATION_MS = 3000;
13→
14→@Injectable()
15→export class GameStateService implements OnDestroy {
16→  private readonly progression = inject(ProgressionService);
17→
18→  private readonly _state = signal<GameState>(GameState.IDLE);
19→  private readonly _currentNote = signal<FretNote | null>(null);
20→  private timerId: ReturnType<typeof setTimeout> | null = null;
21→
22→  readonly state = this._state.asReadonly();
23→  readonly currentNote = this._currentNote.asReadonly();
24→
25→  start(): void {
26→    if (this._state() !== GameState.IDLE) {
27→      return;
28→    }
29→    this._currentNote.set(this.progression.drawNote());
30→    this._state.set(GameState.SHOW_NOTE);
31→    this.startTimer(SHOW_NOTE_DURATION_MS, () => this.showAnswer());
32→  }
33→
34→  showAnswer(): void {
35→    if (this._state() !== GameState.SHOW_NOTE) {
36→      return;
37→    }
38→    this.clearTimer();
39→    this._state.set(GameState.SHOW_ANSWER);
40→    this.startTimer(SHOW_ANSWER_DURATION_MS, () => this.nextNote());
41→  }
42→
43→  nextNote(): void {
44→    if (this._state() !== GameState.SHOW_ANSWER) {
45→      return;
46→    }
47→    this.clearTimer();
48→    this._currentNote.set(this.progression.drawNote());
49→    this._state.set(GameState.SHOW_NOTE);
50→    this.startTimer(SHOW_NOTE_DURATION_MS, () => this.showAnswer());
51→  }
52→
53→  stop(): void {
54→    this.clearTimer();
55→    this._currentNote.set(null);
56→    this._state.set(GameState.IDLE);
57→    this.progression.reset();
58→  }
59→
60→  ngOnDestroy(): void {
61→    this.clearTimer();
62→  }
63→
64→  private startTimer(durationMs: number, callback: () => void): void {
65→    this.clearTimer();
66→    this.timerId = setTimeout(callback, durationMs);
67→  }
68→
69→  private clearTimer(): void {
70→    if (this.timerId !== null) {
71→      clearTimeout(this.timerId);
72→      this.timerId = null;
73→    }
74→  }
75→}
